messages.content:
Tool response:
Tool: find_viable_plasma_specimens
Description: Find Viable Plasma Specimens
Parameters:
    {
      "type": "object",
      "properties": {
        "donor_code": {
          "type": "string",
          "description": "Donor code (e.g., 'DON-7824')",
          "title": "Donor Code"
        },
        "start_date": {
          "type": "string",
          "description": "Start date in YYYY-MM-DD format (e.g., '2023-03-15')",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "description": "End date in YYYY-MM-DD format (e.g., '2023-06-30')",
          "title": "End Date"
        },
        "freezer_unit_code": {
          "type": "string",
          "description": "Freezer unit code (e.g., 'FREEZER-MF-09')",
          "title": "Freezer Unit Code"
        }
      },
      "required": [
        "donor_code",
        "start_date",
        "end_date",
        "freezer_unit_code"
      ]
    }
